void Check(bool value, string message="assertion failed") { if (!value) throw new Exception(message); }
void Test(string name, Action body) { try { body(); results.Add(new {name, passed=true}); Console.WriteLine("PASS " + name); } catch(Exception ex) { results.Add(new {name, passed=false, error=ex.Message}); Console.WriteLine("FAIL " + name + ": " + ex.Message); } }
object Role(string[]? allow=null, string[]? deny=null, string[]? inherits=null, int immunity=0) => new {Allow=allow ?? [],Deny=deny ?? [],Inherits=inherits ?? [],Immunity=immunity};
string Json(Dictionary<string, object>? roles=null, string[]? defaults=null, Dictionary<string,string[]>? users=null, bool root=true)
    => JsonSerializer.Serialize(new {Version=1,CssRootBypass=root,DefaultRoles=defaults ?? ["player"],Roles=roles ?? new Dictionary<string,object>{{"player",Role(["css_ze"])}},Users=users ?? new()});
bool Reject(string text) => !PermissionPolicy.TryParse(text, out var result, out var error) && result==null && error.Length>0;
CCSPlayerController Player(bool auth=true, string id=Id) => new() {SteamID=ulong.Parse(id), AuthorizedSteamID=auth?new TestSteamId{SteamId64=ulong.Parse(id)}:null};
(ZePracticePlugin Plugin, ZePermissionService Service) Service(string? json=null)
{
    var plugin=new ZePracticePlugin{ModuleDirectory=Path.Combine(temp,Guid.NewGuid().ToString("N"))};
    var service=new ZePermissionService(plugin);
    if(json!=null){Directory.CreateDirectory(Path.GetDirectoryName(service.ConfigurationPath)!);File.WriteAllText(service.ConfigurationPath,json,new UTF8Encoding(false));}
    service.Initialize();return(plugin,service);
}
