Test("template matches embedded default",()=>{
    var template=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"permissions.template.json")).Trim();
    var embedded=PermissionPolicy.DefaultJson.Trim();
    int first=Enumerable.Range(0,Math.Min(template.Length,embedded.Length)).FirstOrDefault(i=>template[i]!=embedded[i],-1);
    Check(template==embedded,$"default template differs: template chars={template.Length}, embedded chars={embedded.Length}, first={first}");
});
