var failed=results.Count(x=>x.GetType().GetProperty("passed")!.GetValue(x) is false);
File.WriteAllText(Path.Combine(temp,"results.json"),JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));
Console.WriteLine($"Permissions: {results.Count-failed}/{results.Count}; results: {temp}");
return failed==0?0:1;
